<section class="encode-card" aria-labelledby="linkedTrainingTitle">
  <div class="section-heading">
    <span class="step-icon"><i class="bi bi-link-45deg" aria-hidden="true"></i></span>
    <div><span class="section-kicker">LINKED TRAINING</span><h2 id="linkedTrainingTitle">Training details</h2><p>These fields are filled from the single training selected above.</p></div>
  </div>
  <div class="training-link-fields">
    <div class="training-link-id"><label for="trainingTitleValue">Training ID and title</label><input id="trainingTitleValue" class="form-control" readonly placeholder="Select one approved training above"></div>
    <div><label for="trainingOrganizationValue">Organization</label><input id="trainingOrganizationValue" class="form-control" readonly placeholder="Filled by selected training"></div>
    <div><label for="trainingLocationValue">Location</label><input id="trainingLocationValue" class="form-control" readonly placeholder="Filled by selected training"></div>
    <div><label for="trainingVenueValue">Venue</label><input id="trainingVenueValue" class="form-control" readonly placeholder="Filled by selected training"></div>
    <div class="training-link-dates"><div><label for="trainingStartDateValue">Training starts</label><input id="trainingStartDateValue" class="form-control" readonly placeholder="Select a training"></div><div><label for="trainingEndDateValue">Training ends</label><input id="trainingEndDateValue" class="form-control" readonly placeholder="Select a training"></div></div>
  </div>
  <p class="training-link-hint">The assessment date is prefilled with the training start date. Adjust it if the assessment took place on another day.</p>
</section>
